Item.method_code:
const {
	commandFactory,
	itemType,
	getState,
	rows
} = options;
const { grid } = getState();
if (grid.selectedRows.length !== 1) {
	return { hidden: true };
}

const selectedItemId = grid.selectedRows[0];
const relationshipItem = rows.get(selectedItemId);
const commandAlias = target['command_alias@keyed_name'];
const openCommand = commandFactory(commandAlias, {
	item: relationshipItem,
	itemType
});

return {
	hidden: !openCommand.canExecute()
};
